export const CANVAS_BODY = "<main class=\"editor\">\n  <div class=\"canvas\">\n    <div id=\"vp\">\n      <div id=\"world\">\n        <svg id=\"wires\"></svg>\n        <div id=\"chrome\"></div>\n      </div>\n    </div>\n    <div class=\"tooltip\" id=\"snapinfo\" role=\"status\"></div>\n    <div class=\"canvas-empty\" id=\"canvas-empty\" hidden>\n      <div class=\"empty\">\n        <span class=\"icon\" aria-hidden=\"true\">movie</span>\n        <p class=\"empty__title\">Comece pelos seus vídeos</p>\n        <p>Traga os ganchos, o corpo e os CTAs, encaixe e ligue ao Final.</p>\n        <div class=\"row\">\n          <button class=\"button button--filled interactive\" type=\"button\" data-open-library><span class=\"icon\">video_library</span>Seus vídeos</button>\n          <button class=\"button button--outlined interactive\" type=\"button\" data-open-file><span class=\"icon\">upload</span>Do computador</button>\n        </div>\n      </div>\n    </div>\n    <div class=\"float-bar\" role=\"toolbar\" aria-label=\"Canvas\">\n      <button class=\"icon-button interactive\" type=\"button\" id=\"undo\" aria-label=\"Desfazer\" title=\"Desfazer (Ctrl+Z)\"><span class=\"icon\">undo</span></button>\n      <button class=\"icon-button interactive\" type=\"button\" id=\"redo\" aria-label=\"Refazer\" title=\"Refazer (Ctrl+Shift+Z)\"><span class=\"icon\">redo</span></button>\n      <span class=\"float-bar__divider\"></span>\n      <button class=\"icon-button interactive\" type=\"button\" id=\"zoom-out\" aria-label=\"Diminuir o zoom\" title=\"Diminuir o zoom\"><span class=\"icon\">remove</span></button>\n      <span class=\"float-bar__zoom\" id=\"zoom\">100%</span>\n      <button class=\"icon-button interactive\" type=\"button\" id=\"zoom-in\" aria-label=\"Aumentar o zoom\" title=\"Aumentar o zoom\"><span class=\"icon\">add</span></button>\n      <button class=\"icon-button interactive\" type=\"button\" id=\"arrange\" aria-label=\"Organizar\" title=\"Organizar\"><span class=\"icon\">flowchart</span></button>\n      <button class=\"icon-button interactive\" type=\"button\" id=\"fit\" aria-label=\"Ver tudo\" title=\"Ver tudo\"><span class=\"icon\">fit_screen</span></button>\n      <button class=\"icon-button interactive\" type=\"button\" id=\"info\" popovertarget=\"info-tip\" aria-label=\"Info\" title=\"Info\"><span class=\"icon\">info</span></button>\n    </div>\n  </div>\n  <aside class=\"viewer__sheet\" aria-label=\"Prévia e ajustes\">\n    <div class=\"tabs\" role=\"tablist\">\n      <button class=\"tabs__tab interactive\" type=\"button\" role=\"tab\" data-tab=\"previa\" aria-selected=\"true\"><span class=\"tabs__content\"><span class=\"icon\">play_circle</span>Prévia</span></button>\n      <button class=\"tabs__tab interactive\" type=\"button\" role=\"tab\" data-tab=\"ajustes\" aria-selected=\"false\"><span class=\"tabs__content\"><span class=\"icon\">tune</span>Ajustes</span></button>\n    </div>\n    <div class=\"viewer__body sheet-body\" data-tab=\"previa\">\n      <div class=\"preview\" data-panel=\"previa\">\n        <div class=\"preview__stage\"><div class=\"player__frame\" id=\"pv-stage\"></div></div>\n        <div class=\"vbar\" role=\"group\" aria-label=\"Controles da prévia\">\n          <button class=\"vbar__play interactive\" type=\"button\" id=\"pv-play\" aria-label=\"Tocar\" title=\"Tocar\"><span class=\"icon\">play_arrow</span></button>\n          <span class=\"vbar__time\" id=\"pv-time\">0:00.0 / 0:00.0</span>\n          <input class=\"vbar__seek\" type=\"range\" id=\"pv-slider\" min=\"0\" max=\"1\" step=\"0.01\" value=\"0\" aria-label=\"Posição na prévia\">\n        </div>\n        <p class=\"preview__title\" id=\"pv-title\"></p>\n      </div>\n      <div id=\"side\" data-panel=\"ajustes\" hidden></div>\n    </div>\n    <div class=\"viewer__actions\" id=\"side-actions\" hidden></div>\n  </aside>\n</main>\n<div class=\"rich-tooltip\" id=\"info-tip\" popover=\"auto\" aria-labelledby=\"info-title\">\n  <h2 class=\"rich-tooltip__subhead\" id=\"info-title\">Como usar o canvas</h2>\n  <dl class=\"rich-tooltip__list\">\n    <div><dt>Arraste</dt><dd>para mover</dd></div>\n    <div><dt>Encoste do lado</dt><dd>para juntar</dd></div>\n    <div><dt>Solte em cima</dt><dd>para cobrir</dd></div>\n    <div><dt>Puxe um ponto</dt><dd>para ligar</dd></div>\n    <div><dt>Puxe a linha</dt><dd>para soltar ou trocar</dd></div>\n    <div><dt>Clique na linha e Delete</dt><dd>para apagar</dd></div>\n    <div><dt>Ctrl + roda</dt><dd>para o zoom</dd></div>\n    <div><dt>Dois cliques</dt><dd>para ampliar o bloco</dd></div>\n    <div><dt>Clique no bloco e Espaço</dt><dd>para tocar dali</dd></div>\n    <div><dt>Alt ao arrastar</dt><dd>para soltar sem encaixar</dd></div>\n    <div><dt>Botão direito no Final</dt><dd>para baixar</dd></div>\n  </dl>\n  <div class=\"rich-tooltip__actions\"><button class=\"button button--text interactive\" type=\"button\" popovertarget=\"info-tip\" popovertargetaction=\"hide\">Entendi</button></div>\n</div>\n<div class=\"menu__list fin-menu\" id=\"fin-menu\" role=\"menu\" popover=\"manual\"></div>\n<dialog class=\"dialog library-dialog\" id=\"dlg\" aria-labelledby=\"dlg-title\">\n  <h3 id=\"dlg-title\">Exportar</h3>\n  <p id=\"dlg-text\" role=\"status\"></p>\n  <div class=\"linear-progress\" id=\"dlg-progress\" role=\"progressbar\" aria-label=\"Exportando\" aria-valuemin=\"0\" aria-valuemax=\"100\"></div>\n  <div class=\"xlist\" id=\"dlg-list\"></div>\n  <div class=\"dialog__actions\">\n    <button class=\"button button--text interactive\" type=\"button\" id=\"dlg-close\">Fechar</button>\n    <a class=\"button button--filled interactive\" id=\"dlg-zip\" hidden><span class=\"icon\">download</span>Baixar todas</a>\n  </div>\n</dialog>\n<dialog class=\"dialog library-dialog\" id=\"lib-dlg\" aria-labelledby=\"lib-title\">\n  <h3 id=\"lib-title\">Seus vídeos</h3>\n  <p>Escolha os vídeos prontos que entram no canvas.</p>\n  <div class=\"xlist\" id=\"lib-list\"></div>\n  <div class=\"dialog__actions\"><button class=\"button button--text interactive\" type=\"button\" id=\"lib-close\">Fechar</button></div>\n</dialog>\n<input type=\"file\" id=\"file\" accept=\"video/*,image/*,audio/*\" multiple hidden>\n<div class=\"snackbar\" id=\"toast\" role=\"status\" hidden><span class=\"snackbar__text\" id=\"toast-text\"></span><div class=\"linear-progress\" id=\"toast-progress\" role=\"progressbar\" aria-label=\"Enviando\" hidden></div></div>";

